type Snapshot={layoutVersion?:number;customTemplateId?:string;layers:Layer[];type:string;format:PosterFormat;family:string;primary:string;secondary?:string;motion:string;duration?:number;plans?:string[];sourceMaster?:{name:string;version:number};name:string};
type Saved=Snapshot&{version:number;status:'Concept'|'Gepubliceerd';date:string};
const makeInitial=(primary='#1464f4',secondary='#ffffff'):Snapshot=>({layoutVersion:4,layers:defaultLayers('Einduitslag','portrait','Penseelkracht',primary,secondary),type:'Einduitslag',format:'portrait',family:'Penseelkracht',primary,secondary,motion:'Score reveal',duration:1.2,plans:['Start','Club','Pro'],name:'Einduitslag · Penseelkracht'});
const legacyLayerColors:Record<string,string>={photo:'#ffffff',crest:'#ffffff',club:'#ffffff',competition:'#d9e6ff',accent:'#c8ff24',label:'#ffffff',score:'#ffffff',opponent:'#dae5f8',date:'#a3bada',sponsor:'#ffffff'};
function composeFamilyLayers(current:Snapshot,format:PosterFormat,family:string):Layer[]{
 const next=defaultLayers(current.type,format,family,current.primary,current.secondary),previous=current.layoutVersion===4?defaultLayers(current.type,current.format,current.family,current.primary,current.secondary):legacyDefaultLayers(current.type,current.format,current.family,current.primary);
 const rebuilt=next.map(base=>{const original=current.layers.find(layer=>layer.id===base.id);if(!original)return base;const oldBase=previous.find(layer=>layer.id===base.id);const ownColor=original.color!==oldBase?.color&&!((current.layoutVersion||1)<2&&original.color===legacyLayerColors[base.id]);const ownFont=original.font&&original.font!==oldBase?.font;const ownStyle=Object.fromEntries((['weight','opacity','outline','tracking'] as const).filter(key=>(original as any)[key]!==undefined&&(original as any)[key]!==((oldBase as any)?.[key])).map(key=>[key,(original as any)[key]]));return {...base,...ownStyle,text:base.kind==='photo'&&original.text===oldBase?.text?base.text:original.text,binding:original.binding,visible:original.visible,locked:original.locked,...(ownColor?{color:original.color}:{}),...(ownFont?{font:original.font}:{})};});
 return [...rebuilt,...current.layers.filter(layer=>!next.some(base=>base.id===layer.id))];
}


function upgradeDefaultSnapshot(current:Snapshot):Snapshot{
 if(!Array.isArray(current.layers))return makeInitial(current.primary,current.secondary);
 if(templateCatalog.some(t=>t.name===current.family))return {...current,layoutVersion:4,secondary:current.secondary||'#ffffff'};
 // Retain the old snapshot in Undo; carry its content into the new selected catalogue.
 const family=resolveTemplateName(current.family),base=makeInitial(current.primary,current.secondary);
 return {...base,type:current.type,format:current.format,name:`${current.type} · ${family}`,layers:composeFamilyLayers(current,current.format,family)};
}
function withPalette(current:Snapshot,primary:string,secondary:string):Snapshot{
 const old=defaultLayers(current.type,current.format,current.family,current.primary,current.secondary);
 const next=defaultLayers(current.type,current.format,current.family,primary,secondary);
 return {...current,primary,secondary,layers:current.layers.map(layer=>{
  const before=old.find(l=>l.id===layer.id),after=next.find(l=>l.id===layer.id);
  return before&&after&&layer.color===before.color?{...layer,color:after.color}:layer;
 })};
}

