     {inspector==='Controle'&&<><div className="studio-panel-title"><span>Brand Guard</span><ShieldCheck size={16}/></div><div className={`studio-guard-result ${guardIssues.length?'warning':''}`}><ShieldCheck size={26}/><strong>{guardIssues.length?'Nog even controleren':'Klaar voor jouw club'}</strong><p>{guardIssues.length?guardIssues.join(' '):'Clubembleem, formaat en sponsorregels zijn in orde.'}</p></div>{[{label:'Clubembleem aanwezig',valid:!!snapshot.layers.find(l=>l.kind==='crest'&&l.visible)},{label:'Minimale logobreedte 5,5%',valid:!!snapshot.layers.find(l=>l.kind==='crest'&&l.size>=55)},{label:'Laagankers binnen het canvas',valid:snapshot.layers.filter(l=>l.visible).every(l=>l.x>=0&&l.x<=100&&l.y>=0&&l.y<=100)},{label:'Sponsorregels per berichttype',valid:!(['Rode kaart','Afgelasting'].includes(snapshot.type)&&snapshot.layers.some(l=>l.kind==='sponsor'&&l.visible))},{label:'Bestaande posts blijven ongewijzigd',valid:true}].map(t=><div key={t.label} className={'studio-guard-item '+(!t.valid?'studio-guard-warning':'')}><CheckCircle2 size={15}/><span>{t.label}</span><strong>{t.valid?'OK':'Controle'}</strong></div>)}{isPlatform&&<div className="studio-control"><label>De standaardcollectie</label><p className="studio-field-hint">Alle 27 ontwerpen zijn voor iedere club inbegrepen. Gebruik Maatwerk om een exclusieve clubvariant toe te wijzen.</p><button className="studio-btn studio-full" onClick={()=>setTab(customTab)}><Sparkles size={14}/> Clubmaatwerk beheren</button></div>}<div className="studio-control"><label>Versiebeheer</label><p className="studio-field-hint">Bewaar een vaste versie van dit ontwerp. De 27 standaardtemplates blijven voor iedereen beschikbaar; exclusieve clubtemplates worden via Maatwerk toegewezen.</p></div><button className="studio-btn studio-btn-lime studio-full" onClick={()=>save('Gepubliceerd')}><CheckCircle2 size={15}/> Ontwerpversie vastleggen</button></>}
